try{window.BOSSVOICE={"sentinel_p2":{"text":"Intruder. The seal will hold.","dur":3.15,"env":"000798865559877787774000000985446877777777777646977766554332100"},"sentinel_p3":{"text":"Ruin answers ruin.","dur":2.72,"env":"0008987666666410067766444577765310057887777655444321000"},"sentinel_p4":{"text":"I am the last door. I will not open.","dur":3.82,"env":"00078887777777877777775420078777666631000000189998888877631688841775555431000"},"sentinel_death":{"text":"The seal... is yours to keep.","dur":2.83,"env":"000798644487778777762000798778877777652386248875422322000"},"sovereign2_p2":{"text":"Kneel, and burn with my kingdom!","dur":2.11,"env":"0004676886536752898766417752336664543211000"},"sovereign2_p3":{"text":"Ash is all that kneels before me!","dur":2.37,"env":"000588755675528996894678888742064226886653321000"},"sovereign2_p4":{"text":"Witness the crown of the sun!","dur":1.98,"env":"0004893476424623687666743543356543332000"},"sovereign2_death":{"text":"My fire... was never meant to fade.","dur":2.56,"env":"0005776225987676530366457886587775144225765433221000"},"empress_p2":{"text":"Winter does not end. It waits.","dur":2.54,"env":"000589844636754688633466554431110274457764124432000"},"empress_p3":{"text":"Be still. Be silent. Be frozen.","dur":2.36,"env":"000885536997750764559988665440663279996465650000"},"empress_p4":{"text":"A thousand years of snow... fall now!","dur":2.79,"env":"00065107888856874578755555568754440010012898888765443000"},"empress_death":{"text":"At last... the thaw.","dur":1.73,"env":"00067379888745545437412898765421000"},"saint_p2":{"text":"The garden remembers what you broke.","dur":3.17,"env":"0004726899994376447878986543323654200000000134554266764220031000"},"saint_p3":{"text":"Root and thorn, take back the grove.","dur":3.67,"env":"00049853004127642137777643112100000000000005446343566413353365533222331000"},"saint_p4":{"text":"I have no name. Only the grove.","dur":3.44,"env":"000354345326776555543221110000000000000004987666354335654322212322000"},"saint_death":{"text":"The roots... let me go.","dur":2.04,"env":"00046547986310344320000364463466543222000"},"varkhazan_p2":{"text":"The sky is my grave, and yours.","dur":3.06,"env":"00025332599987666435655433666655444201134444445555433321111000"},"varkhazan_p3":{"text":"Hear the storm that buried my kin!","dur":3.15,"env":"001279985854431787776555653221777776654345544420222554433332000"},"varkhazan_p4":{"text":"The sky tears open at my command!","dur":3.28,"env":"000353331799988751225666534567621554443234444212444444444333221000"},"varkhazan_death":{"text":"The storm... falls silent.","dur":2.57,"env":"0003653321998877666520117776665322222666655444432110"},"worldeater0_p2":{"text":"Do you feel it? Gravity is failing.","dur":3.11,"env":"000577896222498987653011002588997475665354641006666654333321000"},"worldeater0_p3":{"text":"Everything ends in the hunger.","dur":2.85,"env":"000699569723877500467766544335410466653322676663443221000"},"worldeater0_p4":{"text":"I am only its shadow. Imagine the rest.","dur":3.94,"env":"0006789999407999987664045546777554433200000067888777864446665554776432344302000"},"worldeater0_death":{"text":"Go deeper. It is waiting.","dur":2.69,"env":"000337987753266652024433200355543444433355554333222000"},"fallenstar_p2":{"text":"Even light can break.","dur":1.74,"env":"00067748987698630267646766530222000"},"fallenstar_p3":{"text":"The sky falls with me!","dur":1.83,"env":"0004985435978882179875356157656543000"},"fallenstar_p4":{"text":"Burn in the last light of a dying star!","dur":2.72,"env":"0003497777862676656665433166654354176566653425443332000"},"fallenstar_death":{"text":"So bright... so brief.","dur":1.99,"env":"0003459965689987520233775367655411023000"},"eternalnight_p2":{"text":"Close your eyes. It makes no difference.","dur":3.48,"env":"0003489863346675356654322222000000002545662335666654305742224432222000"},"eternalnight_p3":{"text":"The moon sets. Forever.","dur":2.43,"env":"0003778899876544457742023200000013777764244222000"},"eternalnight_p4":{"text":"Welcome to the eternal night.","dur":2.76,"env":"00035899733366533200000366566542033368644444454322021000"},"eternalnight_death":{"text":"Dawn... I had forgotten dawn.","dur":2.62,"env":"00033899875432100015645632235534852334441565432211000"},"hollowking_p2":{"text":"Kneel before your king.","dur":2.22,"env":"000488988777547633788766765244877665444321000"},"hollowking_p3":{"text":"My oath outlived my kingdom.","dur":2.81,"env":"000389873278876323157864237887543457664347787554443321000"},"hollowking_p4":{"text":"A king without mercy needs no crown!","dur":3.31,"env":"0006745598777675787623788765444554324887544787763455877765433331000"},"hollowking_death":{"text":"Take the crown. It was always too heavy.","dur":3.15,"env":"000599743267365798877655430564864288877665304687557865554332100"},"worldeater_p2":{"text":"Worlds are only bread to me.","dur":2.81,"env":"000347899888653477655665555532046666431334444433332111000"},"worldeater_p3":{"text":"Gravity bends. The stars go dark.","dur":3.49,"env":"0002268899658576537766655542212533325777666653212555432465554432001110"},"worldeater_p4":{"text":"This is the last silence.","dur":3.34,"env":"0003479832798545877888887532111222666666554444321111111000000001100"},"worldeater_death":{"text":"Then... let it all begin again.","dur":2.98,"env":"000379988876435899857755467777435532265554432355544433321100"}}}catch(e){console.error('BOSSVOICE',e)}
